#include <iostream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;

unordered_map<string, string> parent;
unordered_map<string, long long> groupSize;
long long groups = 0;
bool countNew = false;

void add(const string& x) {
    if (!parent.count(x)) {
        parent[x] = x;
        groupSize[x] = 1;
        if (countNew) ++groups;
    }
}

string find(string x) {
    add(x);
    string root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != root) {
        string next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

int main() {
    vector<string> data;
    string line;
    while (getline(cin, line)) {
        size_t a = line.find_first_not_of(" \t\r");
        if (a == string::npos) continue;
        data.push_back(line.substr(a));
    }
    size_t start = 0;
    long long n = 0;
    if (!data.empty() && isdigit(static_cast<unsigned char>(data[0][0]))) {
        istringstream header(data[0]);
        header >> n;
        start = 1;
    }
    countNew = (n == 0);
    groups = n;
    for (long long k = 0; k < n; ++k) add(to_string(k));
    for (size_t i = start; i < data.size(); ++i) {
        istringstream in(data[i]);
        string cmd, a, b;
        in >> cmd >> a >> b;
        for (auto& ch : cmd) ch = static_cast<char>(toupper(static_cast<unsigned char>(ch)));
        if (cmd == "UNION") {
            string ra = find(a), rb = find(b);
            if (ra != rb) {
                if (groupSize[ra] < groupSize[rb]) swap(ra, rb);
                parent[rb] = ra;
                groupSize[ra] += groupSize[rb];
                --groups;
            }
        } else if (cmd == "CONNECTED" || cmd == "FIND" || cmd == "SAME") {
            cout << (find(a) == find(b) ? "YES" : "NO") << "\n";
        } else if (cmd == "SIZE") {
            cout << groupSize[find(a)] << "\n";
        } else if (cmd == "COUNT") {
            cout << groups << "\n";
        }
    }
    return 0;
}
