    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    vector<long long> arr(n + 1);
    for (int i = 1; i <= n; ++i) cin >> arr[i];

    SegmentTree st(arr);

    int q;
    if (!(cin >> q)) return 0;
    while (q--) {
        string op;
        cin >> op;
        if (op == "SUM") {
